const money=n=>`$${Number(n||0).toLocaleString()} TTD`, escapeHtml=s=>String(s??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
async function api(action,payload={},token=state.token){const r=await fetch(API,{method:"POST",headers:{"content-type":"application/json",...(token?{authorization:`Bearer ${token}`}:{})},body:JSON.stringify({action,...payload})});const j=await r.json().catch(()=>({error:"The server returned an unreadable response."}));if(!r.ok)throw new Error(j.error||"Something went wrong.");return j}
