function playSound(kind="message"){try{const A=window.AudioContext||window.webkitAudioContext,a=new A,o=a.createOscillator(),g=a.createGain();o.frequency.value=kind==="alert"?880:620;o.type="sine";g.gain.setValueAtTime(.0001,a.currentTime);g.gain.exponentialRampToValueAtTime(.12,a.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.22);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.24)}catch(_){}}
function nav(view){if(state.dirtyAvailability&&state.view==="admin"&&state.adminTab==="availability"){if(confirm("You have unsaved availability changes. Stay here to save them?"))return;state.dirtyAvailability=false;state.draftDates.clear();state.draftRemove.clear()}state.view=view;$$('[data-view]').forEach(b=>b.classList.toggle("active",b.dataset.view===view));window.scrollTo({top:0,behavior:"smooth"});render()}
