function durationTotal(){return state.selected.reduce((n,x)=>{const s=state.data?.services?.find(y=>String(y.id)===String(x.id));return n+Number(s?.duration_minutes||60)},0)}
function durationLabel(minutes){const m=Math.max(0,Math.round(Number(minutes)||0)),h=Math.floor(m/60),r=m%60;return h?(r?`${h} hr ${r} min`:`${h} hr`):(r?`${r} min`:"0 min")}
function clockMinutes(v){const m=String(v||"").match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);if(!m)return 0;let h=Number(m[1]),min=Number(m[2]);if(m[3]?.toUpperCase()==="PM"&&h<12)h+=12;if(m[3]?.toUpperCase()==="AM"&&h===12)h=0;return h*60+min}
function statusLabel(s){return ({pending:"Pending",awaiting_deposit:"Awaiting deposit",payment_review:"Deposit under review",confirmed:"Approved",completed:"Completed",declined:"Declined",cancelled:"Cancelled"})[s]||s}
function empty(text){return `<div class="empty">${escapeHtml(text)}</div>`}
