function imageToDataUrl(file){return new Promise((resolve,reject)=>{if(!file||!file.size)return resolve(null);const img=new Image,reader=new FileReader;reader.onerror=reject;reader.onload=()=>img.src=reader.result;img.onerror=reject;img.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.82))};reader.readAsDataURL(file)})}
