async function bootstrap(){try{state.data=await api("bootstrap");state.selected=state.selected.filter(x=>state.data.services?.some(s=>String(s.id)===String(x.id)));saveSelection();if(state.liveTimer)clearInterval(state.liveTimer);state.liveTimer=setInterval(async()=>{if(state.view!=="admin"){try{state.data=await api("bootstrap");render()}catch(_){}}},15000);render()}catch(e){app.innerHTML=`<div class="card"><h2>We couldn’t load the app</h2><p class="muted">${escapeHtml(e.message)}</p><button class="btn" id="retry">Try again</button></div>`;$("#retry").onclick=bootstrap}}
