function slotIsFuture(s){const date=String(s.slot_date||"");if(!date)return false;const now=new Date(),[yy,mm,dd]=date.split("-").map(Number);let raw=String(s.slot_time||"").trim().toUpperCase(),h=0,min=0;const ampm=raw.match(/(AM|PM)$/);raw=raw.replace(/\s*(AM|PM)$/,"").trim();const parts=raw.split(":");h=Number(parts[0])||0;min=Number(parts[1])||0;if(ampm){if(ampm[1]==="PM"&&h<12)h+=12;if(ampm[1]==="AM"&&h===12)h=0}return new Date(yy,mm-1,dd,h,min,0,0)>now}
function calendarHtml(){const y=state.month.getFullYear(),m=state.month.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),map={};(state.data.availability||[]).forEach(s=>{const d=new Date(`${s.slot_date}T12:00:00`);if(d.getFullYear()===y&&d.getMonth()===m&&slotIsFuture(s))(map[s.slot_date]??=[]).push(s)});let cells="";for(let i=0;i<first.getDay();i++)cells+="<div></div>";for(let d=1;d<=days;d++){const key=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`,slots=map[key]||[],selected=state.slot?.slot_date===key;cells+=`<button class="day ${slots.length?"available":""} ${selected?"selected":""}" data-day="${key}" ${slots.length?"":"disabled"}><b>${d}</b>${slots.length?`<small>${slots.length} future appointment${slots.length===1?"":"s"} available</small>`:""}</button>`}return {html:`<div class="calendar"><div class="calendar-head"><button class="icon-btn" id="prevMonth">‹</button><h2>${state.month.toLocaleString("en",{month:"long",year:"numeric"})}</h2><button class="icon-btn" id="nextMonth">›</button></div><div class="weekdays">${["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(x=>`<span>${x}</span>`).join("")}</div><div class="month-grid">${cells}</div><div id="times"></div></div>`,map}}
function scheduleView(){const cal=calendarHtml();app.innerHTML=`<div class="eyebrow">Monthly availability</div><h1 class="page-title">Choose a day and time</h1><p class="muted">Past openings are unavailable. Choose any future date, then select a time.</p>${cal.html}<div class="notice section">Selecting an appointment sends Kirsten a request. It does not confirm the appointment or require payment.</div>`;$("#prevMonth").onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);state.slot=null;render()};$("#nextMonth").onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);state.slot=null;render()};const showTimes=key=>{const all=(cal.map[key]||[]).filter(slotIsFuture),needed=durationTotal(),slots=all.filter((slot,i)=>{const next=all[i+1];return(next?clockMinutes(next.slot_time)-clockMinutes(slot.slot_time):180)>=needed});state.slot=state.slot?.slot_date===key?state.slot:null;$$(".day").forEach(x=>x.classList.toggle("selected",x.dataset.day===key));$("#times").innerHTML=`<h3>Appointments on ${new Date(key+"T12:00:00").toLocaleDateString("en",{weekday:"long",month:"long",day:"numeric"})}</h3><div class="times">${slots.length?slots.map(s=>`<button class="time-chip ${state.slot?.id===s.id?"selected":""}" data-slot='${JSON.stringify(s)}'>${escapeHtml(s.slot_time)}</button>`).join(""):empty("No future times fit this appointment.")}</div><button class="btn section" id="continueBooking">${state.selected.length?"Continue with my services":"Choose services first"}</button>`;$$("[data-slot]").forEach(x=>x.onclick=()=>{state.slot=JSON.parse(x.dataset.slot);$$(".time-chip").forEach(c=>c.classList.toggle("selected",c===x))});$("#continueBooking").onclick=()=>{if(!state.selected.length){state.returnToSchedule=true;return nav("prices")}if(!state.slot)return showToast("Choose a future appointment time first.");bookingDetails()}};$$("[data-day]").forEach(b=>b.onclick=()=>showTimes(b.dataset.day));const initial=state.slot?.slot_date||Object.keys(cal.map).find(k=>cal.map[k].some(slotIsFuture));if(initial)showTimes(initial)}
function effectivePrice(s){return /soak\s*off/i.test(`${s.name||""} ${s.group_name||""}`)?50:Number(s.price||0)}
function isFullSet(s){return /full\s*set/i.test(`${s.name||""} ${s.group_name||""}`)}
function isRefill(s){return /refill/i.test(`${s.name||""} ${s.group_name||""}`)}
function isManicure(s){return /manicure/i.test(`${s.name||""} ${s.group_name||""}`)}
function isNailArt(s){return s.category==="nail_art"||/nail\s*art/i.test(`${s.name||""} ${s.group_name||""}`)}
function serviceNote(s){const n=String(s.note||"");if(isRefill(s))return n||"For existing sets with no more than 1 missing nail";if(isFullSet(s))return n?(n+" · 2+ missing nails is a full set"):"2+ missing nails is a full set";return n}
function groupRank(name){const n=String(name||"").toLowerCase();if(n.includes("acrylic full set"))return 0;if(n.includes("gel-x")||n.includes("gel x"))return 1;if(n==="nail art"||n.includes("nail art"))return 2;if(n.includes("refill"))return 3;if(n.includes("toe"))return 4;if(n.includes("add-on")||n.includes("addon"))return 5;return 10}
function serviceOrder(a,b){const ta=String(a.name||"").match(/tier\s*(\d+)/i),tb=String(b.name||"").match(/tier\s*(\d+)/i);if(ta&&tb)return Number(ta[1])-Number(tb[1]);if(ta)return -1;if(tb)return 1;return (a.sort_order||999)-(b.sort_order||999)||String(a.name||"").localeCompare(String(b.name||""))}
function pricesView(){const groups=[...new Set(state.data.services.map(s=>s.group_name))].sort((a,b)=>groupRank(a)-groupRank(b)||String(a).localeCompare(String(b)));app.innerHTML=`<div class="eyebrow">Service menu</div><h1 class="page-title">Build your appointment</h1><p class="muted">Choose one hands service, then layer nail art, toes and add-ons. Your estimate updates as you go.</p><div class="service-rule-strip" aria-label="Service rules and shortcuts"><button type="button" class="service-rule-chip" data-jump-group="Acrylic full set">🤎 One hands service</button><button type="button" class="service-rule-chip" data-jump-group="Acrylic full set">🧸 Full set or refill</button><button type="button" class="service-rule-chip" data-jump-group="Structured manicure">🌼 No nail art with manicure</button><button type="button" class="service-rule-chip" data-jump-group="Add-ons">☕ Soak-off · $50</button></div><div id="services">${groups.map(g=>{const rows=state.data.services.filter(s=>s.group_name===g).sort(serviceOrder);return `<section class="service-group" data-service-group="${escapeHtml(g)}"><h3>${escapeHtml(g)}</h3><p class="muted">${rows[0].category==="hands"?"Choose one":rows[0].category==="nail_art"?"Optional · choose one":"Optional · choose any that apply"}</p>${rows.map(s=>`<button class="service-option ${state.selected.some(x=>String(x.id)===String(s.id))?"selected":""}" data-service="${s.id}"><span class="check">${state.selected.some(x=>String(x.id)===String(s.id))?"✓":""}</span><span class="grow"><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(serviceNote(s))}${s.duration_minutes?` · ${Number(s.duration_minutes)} min`:""}${s.special_label?` · ${escapeHtml(s.special_label)}`:""}</small></span><span class="price">${s.price_max&&!/soak\s*off/i.test(`${s.name||""} ${s.group_name||""}`)?`${s.price}–${s.price_max}`:money(effectivePrice(s)).replace(" TTD","")}</span></button>`).join("")}</section>`}).join("")}</div><div class="sticky-summary"><span><small>Estimated total</small><br><strong id="total">${money(total())}</strong></span><span class="estimate-time"><small>Estimated time</small><br><strong id="duration">${durationLabel(durationTotal())}</strong></span><button class="btn" id="toSchedule">Continue</button></div>`;$$("[data-jump-group]").forEach(b=>b.onclick=()=>{const target=$$("[data-service-group]").find(x=>x.dataset.serviceGroup===b.dataset.jumpGroup);if(target){target.scrollIntoView({behavior:"smooth",block:"start"});target.classList.add("jump-highlight");setTimeout(()=>target.classList.remove("jump-highlight"),900)}});$$("[data-service]").forEach(b=>b.onclick=()=>{const s=state.data.services.find(x=>String(x.id)===String(b.dataset.service));if(!s)return showToast("That service could not be found. Please refresh.");const chosen=state.selected.some(x=>String(x.id)===String(s.id));if(chosen){state.selected=state.selected.filter(x=>String(x.id)!==String(s.id))}else{const selectedServices=state.selected.map(x=>state.data.services.find(y=>String(y.id)===String(x.id))).filter(Boolean);if((isManicure(s)&&selectedServices.some(isNailArt))||(isNailArt(s)&&selectedServices.some(isManicure)))return showToast("Manicure and nail art cannot be selected together.");if(isFullSet(s))state.selected=state.selected.filter(x=>{const y=state.data.services.find(z=>String(z.id)===String(x.id));return !y||!isRefill(y)});if(isRefill(s))state.selected=state.selected.filter(x=>{const y=state.data.services.find(z=>String(z.id)===String(x.id));return !y||!isFullSet(y)});if(s.category==="hands")state.selected=state.selected.filter(x=>x.category!=="hands");else if(s.selection_rule==="one")state.selected=state.selected.filter(x=>x.category!==s.category);state.selected.push({id:s.id,label:`${s.group_name} · ${s.name}`,price:effectivePrice(s),category:s.category})}saveSelection();render()});$("#toSchedule").onclick=()=>{const chosen=state.selected.map(x=>state.data.services.find(y=>String(y.id)===String(x.id))).filter(Boolean);if(!chosen.some(x=>x.category==="hands"))return showToast("Choose one hands service before continuing.");nav("schedule")}}

function bookingDetails(){openModal(`<div class="eyebrow">Request your spot</div><h2>${new Date(state.slot.slot_date+"T12:00:00").toLocaleDateString("en",{weekday:"long",month:"long",day:"numeric"})} · ${state.slot.slot_time}</h2><p class="muted">Estimated total: <b>${money(total())}</b><br>Estimated appointment time: <b>${durationLabel(durationTotal())}</b><br>$100 non-refundable deposit is due after confirmation of appointment.</p><form class="form" id="bookingForm"><label class="field">Full name<input name="fullName" required value="${escapeHtml(state.profile?.fullName||"")}"></label><label class="field">WhatsApp number<input name="phone" inputmode="tel" required value="${escapeHtml(state.profile?.phone||"")}"></label><label class="field">Design notes<textarea name="notes" rows="3" placeholder="Shape, colours and inspiration"></textarea></label><label class="upload">Photo of your current nails <small class="muted">Required for first-time clients</small><input name="nailPhoto" type="file" accept="image/*"></label><button type="button" class="btn ghost" id="readPolicies">Read all policies</button><label class="service-option"><input type="checkbox" name="agree" required><span>I agree to the booking, deposit and cancellation policies.</span></label><button class="btn dark" type="submit">Request this appointment</button></form>`);$("#readPolicies").onclick=openPolicyOverlay;$("#bookingForm").onsubmit=submitBooking}
async function submitBooking(e){e.preventDefault();const f=new FormData(e.currentTarget),btn=$("button[type=submit]",e.currentTarget);btn.disabled=true;btn.textContent="Sending request…";try{const nail=await imageToDataUrl(f.get("nailPhoto"));const r=await api("request_booking",{fullName:f.get("fullName"),phone:f.get("phone"),services:state.selected,estimatedTotal:total(),slotId:state.slot.id,designNotes:f.get("notes"),nailPhoto:nail,loyaltyInterest:false});state.selected=[];saveSelection();state.slot=null;closeModal();openModal(`<div class="success"><h2>Request sent</h2><p>Designs by K has been notified. Your request is <b>Pending</b> until Kirsten approves it.</p><p>Save this reference:</p><h2>${r.reference}</h2><p>Payment is due after confirmation.</p></div><div class="actions"><button class="btn" data-view="account">View my request</button><a class="btn secondary" href="${whatsapp(`Hi Kirsten, I requested appointment ${r.reference}.`)}">WhatsApp Kirsten</a></div>`);$('[data-view="account"]',modal).onclick=()=>{closeModal();nav("account")}}catch(err){showToast(err.message);btn.disabled=false;btn.textContent="Request this appointment"}}

function policyModal(returning=false){openModal(policyContent()+`<button class="btn dark" id="closePolicy">${returning?"Continue booking":"Close"}</button>`);$("#closePolicy").onclick=closeModal}
function openPolicyOverlay(){const layer=document.createElement("div");layer.className="policy-overlay";layer.innerHTML=`<div class="modal-box"><button class="icon-btn modal-close">×</button>${policyContent()}<button class="btn dark">Continue booking</button></div>`;modal.appendChild(layer);$$('.modal-close,.btn.dark',layer).forEach(b=>b.onclick=()=>layer.remove())}
function policyContent(){const p=state.data.settings.policies,icons={before:"🧸",booking:"☕",late:"🌼"},labels={before:"Before your appointment",booking:"Booking & deposits",late:"Late arrivals & cancellations"};return `<div class="eyebrow">Please read</div><h2>Designs by K policies</h2><div class="policy-sections">${Object.entries(p).map(([k,v])=>`<section class="policy-card"><div class="policy-card-head"><span>${icons[k]||"🤎"}</span><h3>${labels[k]||k[0].toUpperCase()+k.slice(1)}</h3></div><ul class="policy-list">${v.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul></section>`).join("")}</div>`}
function policiesView(){app.innerHTML=`<div class="eyebrow">Please read</div><h1 class="page-title">Policies</h1>${policyContent().replace('<div class="eyebrow">Please read</div><h2>Designs by K policies</h2>',"")}<a class="whatsapp" href="${whatsapp()}">Questions? Message via WhatsApp</a>`}

function accountView(){if(!state.profile)return loginView();app.innerHTML=`<div class="eyebrow">Your nail space</div><h1 class="page-title">Hi, ${escapeHtml(state.profile.fullName.split(" ")[0])}</h1><div class="loader"><i></i><p>Loading your account…</p></div>`;api(state.profile.role==="admin"?"admin_data":"me").then(data=>{if(state.profile.role==="admin"){state.admin=data;state.view="admin";adminView()}else memberDashboard(data)}).catch(e=>{if(e.message.includes("sign in")){logout();return}app.innerHTML+=`<p>${escapeHtml(e.message)}</p>`})}
function loginView(){app.innerHTML=`<div class="login-card"><div class="eyebrow">Your nail space</div><h1 class="page-title">Welcome back</h1><div class="segmented"><button class="active" data-mode="signin">Sign in</button><button data-mode="register">Create account</button></div><form class="form" id="authForm"><label class="field register-only" hidden>Full name<input name="fullName" autocomplete="name"></label><label class="field">WhatsApp number<input name="phone" inputmode="tel" autocomplete="tel" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" required minlength="4"></label><button class="btn dark">Open my account</button></form><hr><p class="muted">Booking as a guest? Look up one request using either your contact number or booking reference.</p><button class="btn secondary" id="guestLookup">Find my request</button></div>`;let mode="signin";$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle("active",x===b));$(".register-only").hidden=mode!=="register";$("#authForm button").textContent=mode==="signin"?"Open my account":"Create my account"});$("#authForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=$("button",e.currentTarget);btn.disabled=true;try{const r=await api(mode==="signin"?"login":"register",{phone:f.get("phone"),password:f.get("password"),fullName:f.get("fullName")},"");state.token=r.token;state.profile=r.profile;localStorage.setItem("dbk_token",r.token);localStorage.setItem("dbk_profile",JSON.stringify(r.profile));showToast("Welcome to your account.");nav("account")}catch(err){showToast(err.message);btn.disabled=false}};$("#guestLookup").onclick=guestLookupModal}
function logout(){state.token="";state.profile=null;state.admin=null;localStorage.removeItem("dbk_token");localStorage.removeItem("dbk_profile");nav("account")}
function guestLookupModal(){openModal(`<h2>Find my request</h2><p class="muted">Enter either your phone number or booking reference. Phone formatting does not matter.</p><form class="form" id="lookupForm"><label class="field">WhatsApp or contact number <small class="muted">Optional</small><input name="phone" inputmode="tel" placeholder="868 555 1234"></label><label class="field">Booking reference <small class="muted">Optional</small><input name="reference" placeholder="DBK-XXXXXXXX"></label><button class="btn dark">Find request</button></form>`);$("#lookupForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),phone=String(f.get("phone")||"").trim(),reference=String(f.get("reference")||"").trim();if(!phone&&!reference)return showToast("Enter a phone number or booking reference.");try{const r=await api("guest_lookup",{phone,reference},"");renderGuestBooking(r,phone)}catch(err){showToast(err.message)}}}
function renderGuestBooking(r,phone){const b=r.booking;openModal(`<h2>${escapeHtml(b.reference)}</h2>${bookingCard(b)}${b.status==="awaiting_deposit"?depositBox(b,r.settings,phone):""}`);bindDeposit(b,phone)}
function bookingCard(b){return `<article class="card booking-card"><div class="row"><h3>${new Date(b.slot_date+"T12:00:00").toLocaleDateString("en",{month:"short",day:"numeric",year:"numeric"})} · ${escapeHtml(b.slot_time)}</h3><span class="status ${b.status}">${statusLabel(b.status)}</span></div><div class="details">${(b.services||[]).map(x=>escapeHtml(x.label)).join(" + ")}</div><div class="row"><b>${money(Number(b.estimated_total||0)+Number(b.late_fee||0))}</b><small>${escapeHtml(b.reference)}</small></div>${Number(b.late_fee||0)>0?`<div class="fee-note">Includes ${money(b.late_fee)} late fee</div>`:""}</article>`}
function depositBox(b,s,phone=""){return `<section class="section"><div class="bank-card"><div class="eyebrow">Complete your deposit</div><h2>${escapeHtml(s.bank.accountName)}</h2><p>${escapeHtml(s.bank.name)} · ${escapeHtml(s.bank.accountType)}</p><div class="bank-row"><span>Account number</span><b>${escapeHtml(s.bank.accountNumber)}</b></div><div class="bank-row"><span>Transit</span><b>${escapeHtml(s.bank.transit)}</b></div><button class="copy-btn" data-copy="${escapeHtml(s.bank.accountNumber.replace(/\s/g,""))}">Copy account number</button></div><form class="form section deposit-form"><input type="hidden" name="phone" value="${escapeHtml(phone)}"><label class="field">Deposit amount (minimum $100)<input name="amount" type="number" min="100" max="${b.estimated_total}" value="100" required></label><label class="upload">Upload payment receipt<input name="receipt" type="file" accept="image/*" required></label><button class="btn dark">Upload receipt for review</button></form></section>`}
function bindDeposit(b,phone){const copy=$("[data-copy]",modal);if(copy)copy.onclick=async()=>{await navigator.clipboard.writeText(copy.dataset.copy);copy.textContent="Copied ✓"};const form=$(".deposit-form",modal);if(form)form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),btn=$("button",form);btn.disabled=true;btn.textContent="Compressing & uploading…";try{await api("upload_receipt",{reference:b.reference,phone:f.get("phone"),amount:f.get("amount"),image:await imageToDataUrl(f.get("receipt"))});closeModal();showToast("Receipt uploaded. Kirsten will review it.");nav("account")}catch(err){showToast(err.message);btn.disabled=false;btn.textContent="Upload receipt for review"}}}
function memberDashboard(d){const bookings=d.bookings||[],upcoming=bookings.filter(b=>!["completed","declined","cancelled"].includes(b.status)),past=bookings.filter(b=>["completed","declined","cancelled"].includes(b.status)),completed=bookings.filter(b=>b.status==="completed").length,cancelled=bookings.filter(b=>b.status==="cancelled").length,memberSince=new Date((d.profile.member_since||d.profile.created_at||new Date().toISOString().slice(0,10))+"T12:00:00").toLocaleDateString("en",{month:"short",year:"numeric"});app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Your nail space</div><h1 class="page-title">Hi, ${escapeHtml(d.profile.full_name.split(" ")[0])}</h1></div><button class="btn ghost" id="logout">Sign out</button></div><div class="client-stats"><div><small>Member since</small><strong>${memberSince}</strong></div><div><small>Appointments attended</small><strong>${completed}</strong></div><div><small>Cancelled</small><strong>${cancelled}</strong></div></div><section class="loyalty-card section"><div class="loyalty-top"><span class="loyalty-badge">🧸</span><div><div class="eyebrow">Loyalty reward</div><h2>${completed>=5?"10% off unlocked ✨":"Your next reward is on us ♡"}</h2></div></div><p class="muted">${completed>=5?"You’ve completed 5+ appointments. Your 10% discount is ready to use.":`${completed}/5 appointments completed · ${5-completed} more to unlock 10% off your order.`}</p><div class="loyalty-track" aria-label="${Math.min(5,completed)} of 5 appointments completed"><div class="loyalty-rail"><span class="loyalty-fill" style="width:${Math.min(5,completed)*20}%"></span></div><div class="loyalty-bear" style="left:${Math.min(5,completed)*20}%">🧸</div><div class="loyalty-steps">${[0,1,2,3,4,5].map(n=>`<span class="${n<=completed?"done":""}"><b>${n}</b><small>${n===5?"10% off":n===0?"Start":" "}</small></span>`).join("")}</div></div><small class="loyalty-note">Cancelled appointments don’t count toward your reward.</small></section><section class="section"><h2>Upcoming appointments</h2><div class="grid">${upcoming.length?upcoming.map(b=>`${bookingCard(b)}${b.status==="awaiting_deposit"?`<button class="btn" data-deposit="${b.reference}">Complete deposit</button>`:""}`).join(""):empty("No upcoming appointments yet.")}</div></section><section class="section"><h2>Your account</h2><div class="grid two"><button class="card quick" id="messages"><span class="icon">💬</span><strong>Chat with Kirsten</strong><span class="muted">Messages, photos and late alerts</span></button><button class="card quick" id="nailfies"><span class="icon">✦</span><strong>Upload nailfies</strong><span class="muted">Private or community</span></button><button class="card quick" id="reviews"><span class="icon">★</span><strong>Leave a review</strong><span class="muted">Add a review photo</span></button><button class="card quick" id="profile"><span class="icon">♙</span><strong>Edit profile</strong></button></div></section><section class="section"><h2>Previous appointments</h2><div class="grid">${past.length?past.map(bookingCard).join(""):empty("Your completed appointments will appear here.")}</div></section>`;$("#logout").onclick=logout;$$("[data-deposit]").forEach(x=>x.onclick=async()=>{const b=upcoming.find(v=>v.reference===x.dataset.deposit),r=await api("guest_lookup",{phone:d.profile.phone,reference:b.reference});openModal(`${bookingCard(b)}${depositBox(b,r.settings,d.profile.phone)}`);bindDeposit(b,d.profile.phone)});$("#messages").onclick=()=>messageModal(d);$("#nailfies").onclick=nailfieModal;$("#reviews").onclick=reviewModal;$("#profile").onclick=()=>profileModal(d.profile)}
function messageModal(d){const messages=d.messages||[],upcoming=(d.bookings||[]).filter(b=>!["completed","declined","cancelled"].includes(b.status)),last=messages.at(-1);openModal(`<div class="chat-head"><div><small>PRIVATE CHAT</small><h2>Chat with Kirsten</h2></div><span class="online-dot">Studio inbox</span></div><div class="sms-thread" id="smsThread">${messages.length?messages.map(m=>`<div class="sms-row ${m.sender==="customer"?"mine":"theirs"}"><div class="sms-bubble ${m.kind==="alert"?"alert-bubble":""}">${m.kind==="alert"?`<b>⏰ Late alert · ${m.alert_minutes||0} minutes</b>`:""}${m.body?`<p>${escapeHtml(m.body)}</p>`:""}${m.image_url?`<img src="${m.image_url}" alt="Message attachment">`:""}${Number(m.fee_amount||0)>0?`<strong class="fee-alert">Late fee added: ${money(m.fee_amount)}</strong>`:""}<small>${new Date(m.created_at).toLocaleString("en",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})}</small></div></div>`).join(""):`<div class="chat-empty">Start your private conversation with Kirsten.</div>`}</div><div class="late-alerts"><b>Running late?</b><p class="muted">Send Kirsten a quick alert. Any fee Kirsten applies will appear in your appointment total.</p><label class="field">Appointment<select id="lateBooking">${upcoming.length?upcoming.map(b=>`<option value="${b.id}">${escapeHtml(b.reference)} · ${new Date(b.slot_date+"T12:00:00").toLocaleDateString()}</option>`).join(""):`<option value="">General message (no appointment selected)</option>`}</select></label><div class="alert-chips">${[10,15,30].map(n=>`<button type="button" class="alert-chip" data-late="${n}">${n} min late</button>`).join("")}</div></div><form class="sms-compose" id="messageForm"><label class="attach-btn" title="Add photo">＋<input type="file" name="image" accept="image/*"></label><textarea name="text" rows="1" placeholder="Message Kirsten…"></textarea><button class="send-btn" type="submit" aria-label="Send message">➤</button></form>`);const thread=$("#smsThread");thread.scrollTop=thread.scrollHeight;$("#messageForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=$(".send-btn",e.currentTarget),text=String(f.get("text")||"").trim(),image=await imageToDataUrl(f.get("image"));if(!text&&!image){showToast("Write a message or add a photo.");return}btn.disabled=true;try{await api("message",{text,image});playSound("message");showToast("Message sent to Kirsten.");messageModal(await api("me"))}catch(err){showToast(err.message);btn.disabled=false}};$$("[data-late]").forEach(b=>b.onclick=async()=>{const minutes=Number(b.dataset.late),bookingId=$("#lateBooking")?.value||"",text=`I am running approximately ${minutes} minutes late.`;b.disabled=true;try{const payload=bookingId?{kind:"alert",alertMinutes:minutes,bookingId,text}:{text};await api("message",payload);playSound("alert");showToast("Late message sent to Kirsten.");messageModal(await api("me"))}catch(err){showToast(err.message);b.disabled=false}});if(last?.sender==="kirsten"&&localStorage.getItem("dbk_last_message")!==String(last.id)){playSound(last.kind==="alert"?"alert":"message");localStorage.setItem("dbk_last_message",String(last.id))}}
function nailfieModal(){openModal(`<h2>Upload a nailfie</h2><form class="form" id="nailForm"><label class="upload">Choose nail photo<input type="file" name="image" accept="image/*" required></label><label class="field">Caption<input name="caption"></label><label class="field">Who can see it?<select name="visibility"><option value="private">Only Kirsten</option><option value="community">Share to community after approval</option></select></label><button class="btn dark">Upload nailfie</button></form>`);$("#nailForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api("nailfie",{image:await imageToDataUrl(f.get("image")),caption:f.get("caption"),visibility:f.get("visibility")});closeModal();showToast("Nailfie uploaded.")}}
function reviewModal(){openModal(`<h2>Leave a review</h2><form class="form" id="reviewForm"><label class="field">Rating<select name="rating">${[5,4,3,2,1].map(x=>`<option>${x}</option>`).join("")}</select></label><label class="field">Review<textarea name="text" required rows="4"></textarea></label><label class="upload">Add a photo to your review <small class="muted">Optional</small><input type="file" name="image" accept="image/*"></label><button class="btn dark">Send review</button></form>`);$("#reviewForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=$("button",e.currentTarget);btn.disabled=true;try{await api("review",{rating:f.get("rating"),text:f.get("text"),image:await imageToDataUrl(f.get("image"))});playSound("message");closeModal();showToast("Thank you. Kirsten will review your post.")}catch(err){showToast(err.message);btn.disabled=false}}}
function profileModal(p){openModal(`<h2>Edit profile</h2><form class="form" id="profileForm"><label class="field">Full name<input name="fullName" value="${escapeHtml(p.full_name)}" required></label><label class="field">Where you live<input name="location" value="${escapeHtml(p.location||"")}"></label><button class="btn dark">Save changes</button></form>`);$("#profileForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api("update_profile",{fullName:f.get("fullName"),location:f.get("location")});state.profile.fullName=f.get("fullName");localStorage.setItem("dbk_profile",JSON.stringify(state.profile));closeModal();showToast("Profile updated.");nav("account")}}

function communityView(){const posts=state.data.community||[],reviews=state.data.reviews||[];app.innerHTML=`<div class="eyebrow">The K community</div><h1 class="page-title">Nails, notes & love</h1><p class="muted">Client nailfies appear here after Kirsten approves them. Private uploads stay private.</p><div class="actions"><button class="btn" data-view="account">Upload a nailfie</button></div><section class="section"><h2>Community nailfies</h2><div class="feed">${posts.length?posts.map(p=>`<article class="card post"><img src="${p.image_url}" loading="lazy" alt="Client nailfie"><div class="body"><b>${escapeHtml(p.dbk_profiles?.full_name||"Client")}</b><p>${escapeHtml(p.caption)}</p></div></article>`).join(""):empty("Be the first to share a nailfie.")}</div></section><section class="section"><h2>Client reviews</h2><div class="grid two-md">${reviews.length?reviews.map(r=>`<div class="card"><b>${"★".repeat(r.rating)}</b><p>${escapeHtml(r.body)}</p>${r.image_url?`<img class="review-photo" src="${r.image_url}" alt="Client review photo" loading="lazy">`:""}<small>${escapeHtml(r.dbk_profiles?.full_name||"Client")}</small></div>`).join(""):empty("Reviews will appear here after approval.")}</div></section>`}

