function adminMonthDays(){const m=state.availabilityMonth||new Date(),y=m.getFullYear(),mo=m.getMonth(),n=new Date(y,mo+1,0).getDate(),first=new Date(y,mo,1),out=[];for(let i=0;i<first.getDay();i++)out.push({key:"",day:""});for(let d=1;d<=n;d++)out.push({key:[y,String(mo+1).padStart(2,"0"),String(d).padStart(2,"0")].join("-"),day:d});return out}
