async function unpublishRange(kind,button){const raw=$("#rangeDate")?.value||state.availabilityFocusDate||adminMonthStartKey(),selected=[...state.draftDates].sort(),anchor=new Date(raw+"T12:00:00"),start=new Date(anchor),end=new Date(anchor),localKey=x=>[x.getFullYear(),String(x.getMonth()+1).padStart(2,"0"),String(x.getDate()).padStart(2,"0")].join("-");let ranges=[],label="";if(kind==="day"){const days=selected.length?selected:[raw];ranges=days.map(x=>({start:x,end:x}));label=days.length===1?new Date(days[0]+"T12:00:00").toLocaleDateString("en",{month:"long",day:"numeric",year:"numeric"}):`${days.length} selected days`}else if(kind==="week"){start.setDate(anchor.getDate()-anchor.getDay());end.setDate(start.getDate()+6);ranges=[{start:localKey(start),end:localKey(end)}];label=`the week ${start.toLocaleDateString("en",{month:"short",day:"numeric"})}–${end.toLocaleDateString("en",{month:"short",day:"numeric"})}`}else{const m=state.availabilityMonth||anchor;start.setFullYear(m.getFullYear(),m.getMonth(),1);end.setFullYear(m.getFullYear(),m.getMonth()+1,0);ranges=[{start:localKey(start),end:localKey(end)}];label=m.toLocaleString("en",{month:"long",year:"numeric"})}if(!confirm(`Unpublish all available openings for ${label}?`))return;const original=button?.innerHTML;if(button){button.disabled=true;button.textContent="Removing…"}try{const results=await Promise.all(ranges.map(r=>api("admin_unpublish_range",r))),removed=results.reduce((n,r)=>n+Number(r.removed||0),0);state.draftDates.clear();state.draftRemove.clear();state.dirtyAvailability=false;state.admin=await api("admin_data");showToast(removed?`${removed} opening${removed===1?"":"s"} unpublished.`:"No published openings were found in that range.");adminView()}catch(err){showToast(err.message);if(button){button.disabled=false;button.innerHTML=original}}}
