function adminThread(id,messages){const bookings=(state.admin?.bookings||[]).filter(b=>b.profile_id===id&&!["completed","declined","cancelled"].includes(b.status));openModal(`<div class="chat-head"><div><small>CLIENT CHAT</small><h2>${escapeHtml(messages[0]?.dbk_profiles?.full_name||"Client")}</h2></div><span class="online-dot">Private</span></div><div class="sms-thread">${messages.map(m=>`<div class="sms-row ${m.sender==="kirsten"?"mine":"theirs"}"><div class="sms-bubble ${m.kind==="alert"?"alert-bubble":""}">${m.kind==="alert"?`<b>⏰ Late alert · ${m.alert_minutes||0} minutes</b>`:""}${m.body?`<p>${escapeHtml(m.body)}</p>`:""}${m.image_url?`<img src="${m.image_url}" alt="Message attachment">`:""}${Number(m.fee_amount||0)>0?`<strong class="fee-alert">Fee added: ${money(m.fee_amount)}</strong>`:""}<small>${new Date(m.created_at).toLocaleString("en",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})}</small></div></div>`).join("")}</div><form class="sms-compose" id="replyForm"><textarea name="text" rows="1" required placeholder="Reply to client…"></textarea><button class="send-btn">➤</button></form><section class="late-alerts"><b>Send a running-late alert</b><div class="alert-chips">${[10,15,30].map(n=>`<button class="alert-chip" data-owner-late="${n}">${n} min late</button>`).join("")}</div></section><form class="form late-fee-form" id="lateFeeForm"><h3>Apply a client late fee</h3><p class="muted">The fee will be added to the displayed final appointment total.</p><label class="field">Appointment<select name="bookingId" required>${bookings.map(b=>`<option value="${b.id}">${escapeHtml(b.reference)}</option>`).join("")}</select></label><label class="field">Minutes late<select name="minutes"><option>10</option><option>15</option><option>30</option></select></label><label class="field">Late fee (TTD)<input name="fee" inputmode="numeric" type="number" min="0" required></label><button class="btn dark" ${bookings.length?"":"disabled"}>Send alert and apply fee</button></form>`);$("#replyForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api("admin_message",{profileId:id,text:f.get("text")});playSound("message");state.admin=await api("admin_data");adminThread(id,state.admin.messages.filter(m=>m.profile_id===id))}catch(err){showToast(err.message)}};$$("[data-owner-late]").forEach(b=>b.onclick=async()=>{const n=Number(b.dataset.ownerLate);try{await api("admin_message",{profileId:id,kind:"alert",alertMinutes:n,text:`Kirsten is running approximately ${n} minutes late.`});playSound("alert");state.admin=await api("admin_data");adminThread(id,state.admin.messages.filter(m=>m.profile_id===id))}catch(err){showToast(err.message)}});$("#lateFeeForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),n=Number(f.get("minutes")),fee=Number(f.get("fee"));try{await api("admin_message",{profileId:id,kind:"alert",bookingId:f.get("bookingId"),alertMinutes:n,feeAmount:fee,text:`A ${n}-minute late fee of ${money(fee)} was added to your appointment.`});playSound("alert");state.admin=await api("admin_data");adminThread(id,state.admin.messages.filter(m=>m.profile_id===id))}catch(err){showToast(err.message)}}}
